module float_multi (
	input clk,
	input rst,
	input [31:0] a,
	input [31:0] b,
	output reg [31:0] z
);
	reg [2:0] counter;
	reg [23:0] a_mantissa, b_mantissa, z_mantissa;
	reg [9:0] a_exponent, b_exponent, z_exponent;
	reg a_sign, b_sign, z_sign;
	reg [49:0] product;
	reg guard_bit, round_bit, sticky;

	always@(posedge clk or posedge rst) begin 
		if(rst) begin
			counter <= 3'b0;
		end
		else begin
			case(counter)
				0:	begin
						a_mantissa <= {1'b1,a[22:0]};
						b_mantissa <= {1'b1,b[22:0]};
						a_exponent <= a[30:23];
						b_exponent <= b[30:23];
						a_sign <= a[31];
						b_sign <= b[31];
						counter <= counter + 1;
					end

				default:	begin
							product <= a_mantissa * b_mantissa;
							guard_bit <= product[22];
							round_bit <= product[21];
							sticky <= |product[20:0]; // OR reduction operator
							z_exponent <= a_exponent + b_exponent + guard_bit - round_bit - sticky - 11'd127;

							if(product[47]) begin
								z_mantissa <= product[47:24];
								z_exponent <= z_exponent + 1;
							end
							else begin
								z_mantissa <= product[46:23];
							end

							if(z_exponent > 255) begin
								z_exponent <= 255;
								z_mantissa <= 0;
							end
							else if(z_exponent < 0) begin
								z_exponent <= 0;
							end

							z_sign <= a_sign ^ b_sign;

							counter <= counter + 1;

						end
			endcase
		end
	end

	always@(*) begin
		if(a_exponent == 255 && a_mantissa != 0 || b_exponent == 255 && b_mantissa != 0) begin // nan
			z = {1'b1,{8{1'b1}},23'd0};
		end

		else if((a_exponent == 255 && a_mantissa == 0) || (b_exponent == 255 && b_mantissa == 0)) begin // inf
			z = {z_sign, {8{1'b1}}, 23'd0};
		end
		else if (z_exponent == 255 && z_mantissa != 0) begin // inf
			z = {z_sign, {8{1'b1}}, 23'd0};
		end
		else if (z_exponent == 0 && z_mantissa == 0) begin //zero
			z = {z_sign, 8'd0, 23'd0};
		end
		else begin
			z = {z_sign,z_exponent,z_mantissa[22:0]};
		end
	end
endmodule
